UPDATE vocabulary SET meaning_vi = 'Nghĩa đen:giống như nhai cát&nbsp;&nbsp;Nghĩa bóng:buồn tẻ, tẻ nhạt, vô vị… (như nhai cát ngày này qua ngày khác)&nbsp;Ví dụ:毎日毎日、この窓のそばに座って、何もやらない。この仕事は、砂を噛むようだ。' WHERE word_ja = '砂を噛むよう';
UPDATE vocabulary SET meaning_vi = 'Nghĩa đen:ngay cả con mèo và môi múc canh&nbsp;Nghĩa bóng:tất cả mọi người, không chừa một ai, bất kỳ ai (ngay cả con mèo và môi múc canh cũng…)&nbsp;Ví dụ:猫も杓子もデートをしたいほど、彼はカッコいいわ。' WHERE word_ja = '猫も杓子も';
UPDATE vocabulary SET meaning_vi = 'Nghĩa đen:cá nhỏ nghiến răng&nbsp;&nbsp;Nghĩa bóng:dù tức giận, cay cú, nhưng vì không có sức lực, quyền lực… nên không thể làm gì được.&nbsp;Ví dụ:&nbsp;なんでいつも彼の文句を言うの？それはごまめの歯ぎしりだよ。自分のことを気にした方がいいよ。' WHERE word_ja = '鱓の歯軋り';
UPDATE vocabulary SET meaning_vi = 'Nghĩa đen:&nbsp;trăng và ba ba&nbsp;&nbsp;Nghĩa bóng:&nbsp;khác biệt rõ ràng, ai cũng có thể nhận thấy; một trời một vựcVí dụ:アメリカの政府とイギリスのシステムは、月とすっぽんだ。アメリカには女王さえいないよ。' WHERE word_ja = '月と鼈';
UPDATE vocabulary SET meaning_vi = 'Nghĩa đen:quả rắm cuối của con chồn&nbsp;&nbsp;Nghĩa bóng:điều cuối cùng có thể làm khi bị dồn vào bước đường cùng&nbsp;Ví dụ:この試験、きっと赤点だ。イタチの最後っ屁で、残りの問題は当てずっぽうで答えよう。' WHERE word_ja = 'イタチの最後っ屁';
UPDATE vocabulary SET meaning_vi = 'Nghĩa đen:nhồi nhét như sushi&nbsp;&nbsp;Nghĩa bóng:nhồi nhét lại trong một không gian chật chộiTương đương trong tiếng Việt: chật như nêm cối&nbsp;Ví dụ:ラッシュアワーの池袋行きの山手線は、乗客が寿司詰めの電車に押し入れられるんだ。' WHERE word_ja = '寿司詰め';
UPDATE vocabulary SET meaning_vi = 'Nghĩa đen:trước bữa ăn sáng&nbsp;&nbsp;Nghĩa bóng:nhiệm vụ có thể dễ dàng hoàn thành (xong trước khi ăn sáng)Tương đương trong tiếng Việt: dễ như ăn kẹo&nbsp;Ví dụ:彼に勝つのは朝飯前だ' WHERE word_ja = '朝飯前';
UPDATE vocabulary SET meaning_vi = 'Nghĩa đen:bánh Dango thì hơn là hoa&nbsp;&nbsp;Nghĩa bóng:những thứ thiết thực sẽ tốt hơn những thứ đẹp đẽ chỉ để ngắm nhìn&nbsp;Tương đương trong tiếng Việt: tốt gỗ hơn tốt nước sơn&nbsp;&nbsp;Ví dụ:彼はとってもカッコいいけど、性格が悪い。彼の弟は顔はまあまあだけど、性格が良い。花より団子だね。' WHERE word_ja = '花より団子';
UPDATE vocabulary SET meaning_vi = 'Nghĩa đen:chỉ có cái chết mới chữa được cho kẻ ngu ngốc&nbsp;&nbsp;Nghĩa bóng:sự thiếu hiểu biết không thể chữa khỏi đượcTương đương tiếng Việt: Ngu hết thuốc chữa&nbsp;Ví dụ:&nbsp;ひろき君に、コンロが点いている時は触らないように教えた。でも相変わらず熱いコンロを触って、手を火傷している。馬鹿は死ななきゃ、治らないんだろうね〜。' WHERE word_ja = '馬鹿は死ななきゃ治らない';
UPDATE vocabulary SET meaning_vi = 'Nghĩa đen:Đức Phật ở trong địa ngục&nbsp;&nbsp;Nghĩa bóng:ai đó rất hữu ích xuất hiện trong hoàn cảnh vô cùng tồi tệ&nbsp;&nbsp;Ví dụ:八木先生の教室は、すごく臭い。私の隣の席に座っている友達は毎日コロンをつけているから、地獄に仏だ。その香りが臭い匂いを消してくれる' WHERE word_ja = '地獄に仏';
UPDATE vocabulary SET meaning_vi = 'Nghĩa đen:thủ lĩnh trong nhà&nbsp;&nbsp;Nghĩa bóng:kẻ ở nơi riêng tư thì mạnh miệng lớn tiếng, còn ở chỗ công cộng thì yếu đuối, nhát gan.Tương đương trong tiếng Việt: khôn nhà dại chợ&nbsp;Ví dụ:お兄ちゃんは、家ではうるさくて意地悪だ。でも外へ出たとたん、ネズミみたく、大人しくて恥ずかしがり屋になる。お兄ちゃんは本物の内弁慶なんだ' WHERE word_ja = '内弁慶';
UPDATE vocabulary SET meaning_vi = 'Nghĩa đen:　món mì champon (món mì có nhiều rau, hải sản)&nbsp;Nghĩa bóng:　trộn lẫn những thứ không nên trộn lẫn vào nhau (chẳng hạn như rau và… hải sản)Tương đương tiếng Việt:&nbsp;hổ lốn&nbsp;Ví dụ:&nbsp;昨日の夜、ちほさんがビール、ワイン、ウィスキーを全部混ぜて、ちゃんぽんしちゃったわ！' WHERE word_ja = 'チャンポン';
UPDATE vocabulary SET meaning_vi = 'Nghĩa đen:người không biết gì là Phật&nbsp;&nbsp;Nghĩa bóng:&nbsp;không biết hoặc suy nghĩ về điều gì đó đáng lo ngại làm cho bạn thoải mái hơn; những gì bạn không biết không làm bạn căng thẳngtương tự trong tiếng Việt: Ngu thì sống lâuVí dụ:&nbsp;もし夫が居酒屋で馬鹿なことをするんだったら、知りたくないわ。知らぬが仏だから。' WHERE word_ja = '知らぬが仏';
UPDATE vocabulary SET meaning_vi = 'Nghĩa đen:đẩy rèm bằng cánh tay&nbsp;Nghĩa bóng:việc vô ích, không đáng làm, lãng phí công sứcTương đương trong tiếng Việt:&nbsp;việc tốn công vô ích&nbsp;Ví dụ:ひろきさんはとても頑固なので、彼と言い争うのはまるで暖簾に腕押しだ。' WHERE word_ja = '暖簾に腕押し';
UPDATE vocabulary SET meaning_vi = 'Nghĩa đen:con hẻm nước tiểu&nbsp;Nghĩa bóng:con phố, con hẻm nhỏ bốc mùi, bẩn thỉu&nbsp;Ví dụ:&nbsp;こんな汚い小便横町には、水商売の店がたくさん立ち並んでいるに違いない。' WHERE word_ja = '小便横丁';
